-- Demo data: Operations module group (permits, LOTO, assets, chemicals, PPE,
-- contractors, shifts/fatigue, workforce hours) for Peninsula Demo Pty Ltd.
-- Insert-only, org-scoped, fixed UUIDs (prefix d3......). Run once.
BEGIN;
-- ===================== ASSETS =====================
-- (status set directly; asset_number generated by trigger)

-- Maintenance (inserted chronologically per asset: trigger syncs last_maintained_at)


-- OOS events (insert trigger flags asset out_of_service; only on new OOS asset)



-- ===================== PERMITS =====================










-- ===================== LOTO =====================



-- ===================== CHEMICALS =====================



ON CONFLICT (chemical_id, hazard_class_id) DO NOTHING;


-- Inventory opening balances (transactions below adjust these via trigger)





-- ===================== PPE =====================



-- ===================== CONTRACTORS =====================





-- ===================== FATIGUE / SHIFTS =====================


-- Specific shifts referenced by alerts

-- Routine weekday day shifts, last 6 weeks (deterministic ids via md5)
SELECT md5('demo03-shift-'||w.wid||'-'||d::date)::uuid, 'cf08b453-9d6a-4e70-919f-44a12a35502a', w.wid::uuid, w.site::uuid, d::date,
       (d::date + time '06:30') AT TIME ZONE 'Australia/Sydney',
       (d::date + time '06:30' + make_interval(mins => (w.hrs*60)::int)) AT TIME ZONE 'Australia/Sydney',
       w.hrs, 'standard', 'a5058ba6-2390-42a6-8606-8a5e473a1d0d'
FROM generate_series(date '2026-09-21', date '2026-11-03', interval '1 day') d
CROSS JOIN (VALUES ('a5058ba6-2390-42a6-8606-8a5e473a1d0d','ace8e604-d522-46fa-a114-1acde4a628d7',10.0),
                   ('f982d909-5539-4599-b433-35b864013cb0','dee10365-0895-4989-b8c9-bf464071d81f',8.5),
                   ('04f08446-d191-4065-b19a-b3c08d03da97','ace8e604-d522-46fa-a114-1acde4a628d7',8.0)) w(wid, site, hrs)
WHERE extract(isodow FROM d) < 6
  AND NOT (w.wid='a5058ba6-2390-42a6-8606-8a5e473a1d0d' AND d::date IN ('2026-10-24','2026-10-25'))
  AND NOT (w.wid='f982d909-5539-4599-b433-35b864013cb0' AND d::date IN ('2026-10-30','2026-10-31','2026-11-02'));


-- ===================== WORKFORCE HOURS (monthly, May–Oct 2026) =====================
SELECT md5('demo03-wh-'||x.dept||'-'||m::date)::uuid, 'cf08b453-9d6a-4e70-919f-44a12a35502a', x.site::uuid, x.dept::uuid,
       m::date, (m + interval '1 month - 1 day')::date,
       round(x.hc * 152 * (0.95 + 0.1 * ((extract(month FROM m)::int * 7 + x.seed) % 10) / 10.0)),
       x.hc, CASE WHEN m < date '2026-08-01' THEN 'manual' ELSE 'payroll_import' END,
       'Monthly hours – '||to_char(m,'Mon YYYY'), '27ac6db6-a245-400b-b97d-bcf3178936b2'
FROM generate_series(date '2026-05-01', date '2026-10-01', interval '1 month') m
CROSS JOIN (VALUES
  ('bfefd83a-8a07-4f61-9047-923145501ecb','0bc0f996-3166-49ee-a4c2-cb1f7479d881',4,1),
  ('bfefd83a-8a07-4f61-9047-923145501ecb','9a5f0e1d-a652-4716-90c3-5bd61a00e253',12,2),
  ('bfefd83a-8a07-4f61-9047-923145501ecb','adf4d2fe-b5e9-49bc-a3be-68c3cebfd0d7',3,3),
  ('dee10365-0895-4989-b8c9-bf464071d81f','41cde70b-5e44-4863-acf2-e0f1498a5d94',28,4),
  ('dee10365-0895-4989-b8c9-bf464071d81f','6dfd78a3-bc68-40c5-9c67-c1f563588b3e',6,5),
  ('ace8e604-d522-46fa-a114-1acde4a628d7','f6e064d6-7cc2-42b9-9ecf-606da765c2d9',45,6),
  ('ace8e604-d522-46fa-a114-1acde4a628d7','eb5d6cb8-40f7-40e6-b6eb-b5eb47e12e57',8,7)) x(site, dept, hc, seed)
ON CONFLICT DO NOTHING;

COMMIT;
